sed -i '/Decode google-services.json/,/fi/c\      - name: Decode google-services.json\n        env:\n          GOOGLE_SERVICES_JSON: ${{ secrets.GOOGLE_SERVICES_JSON_BASE64 }}\n        run: |\n          echo "$GOOGLE_SERVICES_JSON" > app/google-services.json.tmp\n          if grep -q "{" app/google-services.json.tmp; then\n            echo "Secret appears to be raw JSON. Writing directly."\n            mv app/google-services.json.tmp app/google-services.json\n          else\n            echo "Secret appears to be base64. Decoding..."\n            base64 -d app/google-services.json.tmp > app/google-services.json\n          fi' .github/workflows/release.yml
